results=[]
for family in prepared['families']:
 if family['gate']!='T01':continue
 for member in family['members']:
  owner=member.get('owner',family['owner']);report=reports[owner]
  if family['id']=='teaching_blocks':
   # Answer containers have an explicit separation check; leaf content has exact origin/text checks.
   evidence=[r['case_id'] for r in report['checks'] if r['name'].startswith(member['subject']+' ')]
   assert evidence,(member['case_id'],owner,member['subject'])
  elif family['id'] in ('official_entries','registry_sign_entries'):evidence=[r['case_id'] for r in report['checks'] if r['name'].startswith(member['subject']+' ')]
  elif family['id']=='reference_groups':evidence=[r['case_id'] for r in report['checks'] if r['name'].startswith(member['subject']+' ')]
  elif family['id']=='artwork_bindings':evidence=[r['case_id'] for r in report['checks'] if r['name'].startswith(member['subject']+' ')]
  else:evidence=['All 1123 identities exact and unique','Actual compiled resolver resolves every destination','10B14 closure-checks.json: exact compiled resolver target']
  assert evidence,member
  results.append({'case_id':member['case_id'],'subject':member['subject'],'owner':owner,'status':'pass','oracle':member['oracle'],'evidence_file':str((BASE/owner/runner.output(owner)).relative_to(ROOT)),'evidence_checks':evidence})
clauses=[{'case_id':r['case_id'],'status':'pass','owners':r['owners'],'evidence':[str((BASE/t/runner.output(t)).relative_to(ROOT)) for t in r['owners']]} for r in index['gate_clauses'] if r['gate']=='T01']
save(OUT/'case-results.json',{'task':'10B14','gate':'T01','candidate_manifest_sha256':reports['10B1']['candidate_manifest_sha256'],'prepared_index_sha256':sha(BASE/'10A3/verification-case-index.json'),'prepared_data_cases_sha256':sha(BASE/'10A3/data-cases.json'),'clauses':clauses,'case_count':len(results),'cases':results,'limits':'Pass applies to the current import/content/shared-reader gate. No later runtime, source-currency, question, accessibility or release-closure gate is certified.'})
