register=json.loads((OUT/'defects.json').read_text())
register['resolved_verification_findings'].append({'id':'DEF-10B-005','scope':'verifier','finding':'PDF line wrap split the approved small waterways phrase','resolution':'Normalize presentation whitespace; exact source block, normalized PDF text and actual reader passage agree.','evidence':'../10B7/initial-correction-diagnostic.txt','status':'closed'})
register['resolved_verification_findings'].append({'id':'DEF-10B-006','scope':'verifier','finding':'Ordered-list children share the full source-list origin','resolution':'Compare each child to its numbered source line; compare parent to the complete ordered list.','evidence':'../10B11/initial-list-diagnostic.txt','status':'closed'})
prepared_register=json.loads((BASE/'10A3/defects.json').read_text())
register.update(schema_version=1,task='10B14',date='2026-10-20',severity_policy=prepared_register['severity_policy'],required_record_fields=prepared_register['required_record_fields'])
