 owner,subject=subjects[item['id']]
 cases=[r['case_id'] for r in results if subject and r['subject'].startswith(subject)] or ['T01-CLAUSE-01']
 findings.append({'id':item['id'],'severity':'P2','state':'closed','type':item['scope'],'detected_in_task':owner,'case_ids':cases,'candidate':{'entry_commit':'24ee146','manifest_sha256':reports['10B1']['candidate_manifest_sha256']},'expected':'Verifier models the approved representation and covers every assigned case.','observed':item['finding'],'reproduction':{'condition':item['finding'],'retained_diagnostic':item['evidence']},'evidence':[item['evidence']],'affected_ids_files':[subject] if subject else ['10B1/ImportVerification10BTest.kt'],'owners':[owner],'impacted_gates':['T01'],'fix_scope':item['resolution'],'approval_if_required':'No new design or product change; verification-only repair within the authorized 10B run.','invalidation':'Supersedes the affected failed verification attempt; product candidate and historical acceptance receipts unchanged.','retest':{'task':owner,'status':'pass','evidence':str((BASE/owner/runner.output(owner)).relative_to(ROOT))},'closure_reason':item['resolution']})
