summary=[]
for task,report in reports.items():
 folder=BASE/task
 if task=='10B14':report['closure_checks']='closure-checks.json'
 row={'task':task,'status':'pass','checks':report['totals']['checks'],'report':runner.output(task),'report_sha256':sha(folder/runner.output(task)),'candidate_manifest_sha256':report['candidate_manifest_sha256'],'source_fingerprint':'ac0d4e6b6b226b1f87f8d09521b4c334cccecd6cb7827c1bbd3889127402973c','candidate_entry_commit':'24ee146','runtime':None}
 runtimefile=folder/('reference-runtime.json' if task=='10B13' else 'reader-runtime.json')
 if runtimefile.exists():
  runtime=json.loads(runtimefile.read_text());row['runtime']={'path':runtimefile.name,'sha256':sha(runtimefile),'observations':len(runtime['observations']),'passed':sum(r['passed'] for r in runtime['observations'])}
 save(folder/'results.json',row);summary.append(row)
 # Reconcile completion counts after supplementary checks.
 plan=ROOT/'docs/curriculum/implementation-plan.md';s=plan.read_text();start=s.index('#### '+task+'.');end=s.find('\n#### ',start+10);end=len(s) if end<0 else end;section=s[start:end]
 section=re.sub(r'\): \d+ checks pass;','): '+str(row['checks'])+' checks pass;',section);s=s[:start]+section+s[end:];plan.write_text(s)
 progress=ROOT/'docs/curriculum/progress.md';s=progress.read_text();s=re.sub(r'(\| '+task+r' \|[^\n]*?Completed; \[)\d+( checks pass\])',lambda m:m[1]+str(row['checks'])+m[2],s);progress.write_text(s)
# Explicit interpretation of the reference runtime and generation closure.
(OUT/'review.md').write_text('# 10B14 — Complete import and generation parity\n\n**20 October 2026 — passed.** All fourteen 10B tasks pass for the unchanged accepted candidate. [Task results](sequence-results.json), [complete import parity](complete-import-parity.json), [independent closure checks](closure-checks.json) and [all prepared T01 cases](case-results.json) retain separate evidence.\n\nThe six content-guide read-only checks pass. Two isolated generation runs produce byte-identical reader/navigation/accepted outputs matching production, and identical complete accepted-package Kotlin and trace outputs. No production generation or historical receipt was overwritten. The separate accepted release remains 1,000 accepted / zero held; the historical 384/616 candidate remains audit data.\n\nAll 578 PDF pages freshly match retained extraction. Independent character-interval accounting covers pages 41–578, including exact shared official cards and declared print furniture. Opening/M01/M02 exact source blocks and all remaining source paragraphs, tables, scenarios, hidden answers, captions, crop/overlay data and compiled fields are checked. The approved page-193 correction is located at M06-L01/teaching-009 and was visually inspected in the approved PDF.\n\nFresh shared-reader runs cover every requested document/block and answer reveal. The reference run visits all 400 sign details and 24 groups, including source/artwork credits. Four fonts and both complete licence texts match approved production bytes. Original prepared case files remain immutable; new execution results are linked here.\n\n[Resolved verifier findings](defects.json) and retained diagnostics explain the preparation repairs. No open product defect or verification blocker was discovered in 10B. Cross-platform presentation/runtime, assistive listening, fresh source currency and other gates remain assigned to their later tasks.\n\n**Stopped after 10B14. Next separately requested task: 10C1.**\n')
folder=BASE/'10B13';s=(folder/'review.md').read_text();s+='\nFresh [reference runtime observations](reference-runtime.json) cover all 400 sign details and 24 groups, including identity, editorial labels, captions, alternative text and source/artwork credit content. These content observations do not establish later native/platform legibility.\n';(folder/'review.md').write_text(s)
save(OUT/'sequence-results.json',{'status':'pass','tasks':summary,'task_count':14,'checks':sum(r['checks'] for r in summary),'additional_closure_checks':closure['totals'],'prepared_T01_case_count':len(results),'T01_clause_count':len(clauses),'next_task':'10C1'})
plan=ROOT/'docs/curriculum/implementation-plan.md';s=plan.read_text();s=s.replace('10A1–10A3 complete; independent T01–T10 execution remains pending.','10A1–10B14 complete; T01 import verification passed, T02–T10 remain pending.');s=s.replace('**Next separately requestable task: 10B1 — verify opening material and canonical structure.**','**Next separately requestable task: 10C1 — audit exact source bindings and classifications.**');plan.write_text(s)
progress=ROOT/'docs/curriculum/progress.md';s=progress.read_text();s=re.sub(r'\*\*Last updated:\*\*[^\n]+','**Last updated:** 20 October 2026 (10A preparation and all 10B import verification completed)',s,count=1);s=re.sub(r'\*\*Next action:\*\*[^\n]+','**Next action:** Separately request **10C1** to audit exact source bindings and classifications. **10A1–10B14 are complete**; the [T01 import verification](app-migration/verification-evidence/10B14/review.md) passes for the unchanged accepted candidate. T02–T10 and final step-10 closure remain pending. The historical 384 accepted / 616 held candidate remains audit data, not the production bank.',s,count=1);s=s.replace('In progress; 10A1–10A3 complete','In progress; 10A–10B complete');s=s.replace('[Preparation evidence](app-migration/verification-evidence/10A3/review.md); T01–T10 remain pending; next is 10B1','[T01 import verification](app-migration/verification-evidence/10B14/review.md); T02–T10 remain pending; next is 10C1');s=s.replace('10A1–10A3 completed sequentially under the user’s request. All other tasks remain unstarted.','10A1–10B14 completed under the user’s requested sequences. T01 import verification passes; all 10C–10M tasks remain unstarted.');s=s.replace('Preparation checks establish identity, scope and case coverage, not T01–T10 functional acceptance.','10A preparation establishes identity, scope and case coverage; 10B records the independently executed T01 import/content gate.');s+='\n**20 October — 10B sequence completed:** All fourteen tasks passed, including exhaustive approved-source/PDF/compiled-content parity, fresh shared-reader and 400-sign/24-group observations, exact assets/fonts/licences, all six read-only generation/release checks and two byte-identical isolated generation runs. All prepared T01 cases have mapped execution evidence. Verification-tool diagnostics were corrected and retained; no production input or historical receipt changed. T02–T10 and final step-10 closure remain pending. [Complete evidence](app-migration/verification-evidence/10B14/review.md). Stopped before 10C1.\n';progress.write_text(s)
